#ifndef ARENA_AST_H
#define ARENA_AST_H

#include <stddef.h>
#include <stdint.h>

typedef struct arena_ast { unsigned char *buf; size_t cap, usati; } arena_ast_t;
typedef enum tipo_val { TV_INT, TV_BOOL, TV_ERR } tipo_val_t;
typedef enum tipo_nodo { N_INT, N_BOOL, N_ADD, N_MUL, N_EQ, N_NOT, N_TERN } tipo_nodo_t;
typedef struct nodo_expr nodo_expr_t;

struct nodo_expr {
    tipo_nodo_t tipo;
    union {
        int64_t val_int;
        bool val_bool;
        struct { const nodo_expr_t *sx, *dx; } bin;
        const nodo_expr_t *unario;
        struct { const nodo_expr_t *cond, *ramo_v, *ramo_f; } tern;
    } dati;
};

bool arena_ast_init(arena_ast_t *a, size_t cap);
void arena_ast_distruggi(arena_ast_t *a);
void *arena_ast_alloca(arena_ast_t *a, size_t dim);
void arena_ast_reset(arena_ast_t *a);
tipo_val_t nodo_verifica_tipo(const nodo_expr_t *n);
size_t nodo_conta(const nodo_expr_t *n);
size_t nodo_profondita(const nodo_expr_t *n);

#endif

