#include "arena_ast.h"
#include <stdckdint.h>
#include <stdlib.h>

bool arena_ast_init(arena_ast_t *a, size_t cap) {
    if (a == nullptr || cap == 0 || cap > 65536) { return false; }
    a->buf = malloc(cap);
    if (a->buf == nullptr) { return false; }
    a->cap = cap;
    a->usati = 0;
    return true;
}

void arena_ast_distruggi(arena_ast_t *a) {
    if (a != nullptr) { free(a->buf); a->buf = nullptr; a->cap = 0; a->usati = 0; }
}

void *arena_ast_alloca(arena_ast_t *a, size_t dim) {
    if (a == nullptr || a->buf == nullptr || dim == 0) { return nullptr; }
    size_t allin = alignof(max_align_t), somma = 0, fine = 0;
    if (ckd_add(&somma, a->usati, allin - 1)) { return nullptr; }
    size_t inizio = somma & ~(allin - 1);
    if (ckd_add(&fine, inizio, dim) || fine > a->cap) { return nullptr; }
    a->usati = fine;
    return a->buf + inizio;
}

void arena_ast_reset(arena_ast_t *a) { if (a != nullptr) { a->usati = 0; } }

tipo_val_t nodo_verifica_tipo(const nodo_expr_t *n) {
    if (n == nullptr) { return TV_ERR; }
    switch (n->tipo) {
        case N_INT: return TV_INT;
        case N_BOOL: return TV_BOOL;
        case N_ADD: case N_MUL:
            return (nodo_verifica_tipo(n->dati.bin.sx) == TV_INT && nodo_verifica_tipo(n->dati.bin.dx) == TV_INT) ? TV_INT : TV_ERR;
        case N_EQ: {
            tipo_val_t ts = nodo_verifica_tipo(n->dati.bin.sx), td = nodo_verifica_tipo(n->dati.bin.dx);
            return (ts != TV_ERR && ts == td) ? TV_BOOL : TV_ERR;
        }
        case N_NOT:
            return (nodo_verifica_tipo(n->dati.unario) == TV_BOOL) ? TV_BOOL : TV_ERR;
        case N_TERN: {
            tipo_val_t tc = nodo_verifica_tipo(n->dati.tern.cond);
            tipo_val_t tv = nodo_verifica_tipo(n->dati.tern.ramo_v), tf = nodo_verifica_tipo(n->dati.tern.ramo_f);
            return (tc == TV_BOOL && tv != TV_ERR && tv == tf) ? tv : TV_ERR;
        }
    }
    return TV_ERR;
}

size_t nodo_conta(const nodo_expr_t *n) {
    if (n == nullptr) { return 0; }
    switch (n->tipo) {
        case N_INT: case N_BOOL: return 1;
        case N_ADD: case N_MUL: case N_EQ: return 1 + nodo_conta(n->dati.bin.sx) + nodo_conta(n->dati.bin.dx);
        case N_NOT: return 1 + nodo_conta(n->dati.unario);
        case N_TERN: return 1 + nodo_conta(n->dati.tern.cond) + nodo_conta(n->dati.tern.ramo_v) + nodo_conta(n->dati.tern.ramo_f);
    }
    return 0;
}

size_t nodo_profondita(const nodo_expr_t *n) {
    if (n == nullptr) { return 0; }
    switch (n->tipo) {
        case N_INT: case N_BOOL: return 1;
        case N_ADD: case N_MUL: case N_EQ: {
            size_t a = nodo_profondita(n->dati.bin.sx), b = nodo_profondita(n->dati.bin.dx);
            return 1 + (a > b ? a : b);
        }
        case N_NOT: return 1 + nodo_profondita(n->dati.unario);
        case N_TERN: {
            size_t a = nodo_profondita(n->dati.tern.cond), b = nodo_profondita(n->dati.tern.ramo_v), c = nodo_profondita(n->dati.tern.ramo_f);
            size_t m = a > b ? a : b; return 1 + (m > c ? m : c);
        }
    }
    return 0;
}

