#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "arena_ast.h"

static const char *nome_tipo(tipo_val_t t) {
    return (t == TV_INT) ? "INT" : ((t == TV_BOOL) ? "BOOL" : "ERRORE");
}

int main(void) {
    arena_ast_t arena = {};
    if (!arena_ast_init(&arena, 4096)) { return EXIT_FAILURE; }
    const nodo_expr_t *slot[32] = {};
    char riga[128], cmd[16], op[16], extra = '\0';
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%15s", cmd) != 1) { continue; }
        size_t id = 0, a = 0, b = 0, c = 0; long long v = 0;
        if (strcmp(cmd, "INT") == 0 && sscanf(riga, "INT %zu %lld %c", &id, &v, &extra) == 2 && id < 32) {
            nodo_expr_t *n = arena_ast_alloca(&arena, sizeof(*n));
            if (n == nullptr || ((uintptr_t)n % alignof(max_align_t)) != 0) { arena_ast_distruggi(&arena); return EXIT_FAILURE; }
            *n = (nodo_expr_t){.tipo = N_INT, .dati.val_int = (int64_t)v}; slot[id] = n;
            printf("OK [%zu] INT\n", id);
        } else if (strcmp(cmd, "BOOL") == 0 && sscanf(riga, "BOOL %zu %lld %c", &id, &v, &extra) == 2 && id < 32 && (v == 0 || v == 1)) {
            nodo_expr_t *n = arena_ast_alloca(&arena, sizeof(*n));
            if (n == nullptr) { arena_ast_distruggi(&arena); return EXIT_FAILURE; }
            *n = (nodo_expr_t){.tipo = N_BOOL, .dati.val_bool = (v != 0)}; slot[id] = n;
            printf("OK [%zu] BOOL\n", id);
        } else if (strcmp(cmd, "BIN") == 0 && sscanf(riga, "BIN %zu %15s %zu %zu %c", &id, op, &a, &b, &extra) == 4 && id < 32 && a < 32 && b < 32 && slot[a] && slot[b]) {
            tipo_nodo_t tn = (strcmp(op, "ADD") == 0) ? N_ADD : ((strcmp(op, "MUL") == 0) ? N_MUL : N_EQ);
            if (strcmp(op, "ADD") != 0 && strcmp(op, "MUL") != 0 && strcmp(op, "EQ") != 0) { arena_ast_distruggi(&arena); return EXIT_FAILURE; }
            nodo_expr_t *n = arena_ast_alloca(&arena, sizeof(*n));
            if (n == nullptr) { arena_ast_distruggi(&arena); return EXIT_FAILURE; }
            *n = (nodo_expr_t){.tipo = tn, .dati.bin = {slot[a], slot[b]}}; slot[id] = n;
            printf("OK [%zu] %s\n", id, op);
        } else if (strcmp(cmd, "NOT") == 0 && sscanf(riga, "NOT %zu %zu %c", &id, &a, &extra) == 2 && id < 32 && a < 32 && slot[a]) {
            nodo_expr_t *n = arena_ast_alloca(&arena, sizeof(*n));
            if (n == nullptr) { arena_ast_distruggi(&arena); return EXIT_FAILURE; }
            *n = (nodo_expr_t){.tipo = N_NOT, .dati.unario = slot[a]}; slot[id] = n;
            printf("OK [%zu] NOT\n", id);
        } else if (strcmp(cmd, "TERN") == 0 && sscanf(riga, "TERN %zu %zu %zu %zu %c", &id, &a, &b, &c, &extra) == 4 && id < 32 && a < 32 && b < 32 && c < 32 && slot[a] && slot[b] && slot[c]) {
            nodo_expr_t *n = arena_ast_alloca(&arena, sizeof(*n));
            if (n == nullptr) { arena_ast_distruggi(&arena); return EXIT_FAILURE; }
            *n = (nodo_expr_t){.tipo = N_TERN, .dati.tern = {slot[a], slot[b], slot[c]}}; slot[id] = n;
            printf("OK [%zu] TERN\n", id);
        } else if (strcmp(cmd, "INFO") == 0 && sscanf(riga, "INFO %zu %c", &id, &extra) == 1 && id < 32) {
            if (slot[id] == nullptr) { printf("INFO[%zu]: VUOTO\n", id); }
            else { printf("INFO[%zu]: nodi=%zu prof=%zu tipo=%s\n", id, nodo_conta(slot[id]), nodo_profondita(slot[id]), nome_tipo(nodo_verifica_tipo(slot[id]))); }
        } else if (strcmp(cmd, "RESET") == 0 && sscanf(riga, "RESET %c", &extra) != 1) {
            arena_ast_reset(&arena); memset(slot, 0, sizeof(slot));
            printf("RESET: usati=%zu\n", arena.usati);
        } else { arena_ast_distruggi(&arena); return EXIT_FAILURE; }
    }
    arena_ast_distruggi(&arena);
    return EXIT_SUCCESS;
}

