#include <inttypes.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "lexer_minil.h"

int main(void) {
    char src[4096] = {};
    size_t tot = 0;
    char riga[256];
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        size_t n = strlen(riga);
        if (tot + n >= sizeof(src)) { return EXIT_FAILURE; }
        memcpy(src + tot, riga, n);
        tot += n;
    }
    src[tot] = '\0';
    lexer_t lx = {};
    lexer_init(&lx, src);
    while (true) {
        token_t t = lexer_prossimo(&lx);
        if (t.tipo == TOK_ERR) {
            printf("ERRORE %zu:%zu: %s\n", t.riga, t.col, t.inizio);
            break;
        }
        if (t.tipo == TOK_INT) { printf("%zu:%zu INT=%" PRId64 "\n", t.riga, t.col, t.val_int); }
        else if (t.tipo == TOK_IDENT) { printf("%zu:%zu IDENT=%.*s\n", t.riga, t.col, (int)t.len, t.inizio); }
        else { printf("%zu:%zu %s\n", t.riga, t.col, tok_nome(t.tipo)); }
        if (t.tipo == TOK_EOF) { break; }
    }
    return EXIT_SUCCESS;
}

