#include "expr_parser.h"
#include <ctype.h>
#include <inttypes.h>
#include <stdckdint.h>
#include <stdio.h>
#include <string.h>

typedef struct parser { expr_arena_t *a; const char *s; size_t pos, prof, err_col; char *err_msg; size_t err_cap; bool err; } parser_t;

static void *a_alloca(expr_arena_t *a, size_t dim) {
    size_t al = alignof(max_align_t), s = 0, f = 0;
    if (ckd_add(&s, a->usati, al - 1)) { return nullptr; }
    size_t ini = s & ~(al - 1);
    if (ckd_add(&f, ini, dim) || f > a->cap) { return nullptr; }
    a->usati = f; return a->buf + ini;
}
static void imp_err(parser_t *p, size_t col, const char *m) {
    if (!p->err) { p->err = true; p->err_col = col; snprintf(p->err_msg, p->err_cap, "%s", m); }
}
static void salta(parser_t *p) { while (p->s[p->pos] != '\0' && isspace((unsigned char)p->s[p->pos])) { ++p->pos; } }
static bool match2(parser_t *p, char a, char b) {
    salta(p); if (p->s[p->pos] == a && p->s[p->pos + 1] == b) { p->pos += 2; return true; } return false;
}
static bool match1_noeq(parser_t *p, char a) {
    salta(p); if (p->s[p->pos] == a && p->s[p->pos + 1] != '=') { ++p->pos; return true; } return false;
}
static enodo_t *mk_bin(parser_t *p, const char *op, enodo_t *sx, enodo_t *dx) {
    enodo_t *n = a_alloca(p->a, sizeof(*n)); if (n == nullptr) { imp_err(p, p->pos + 1, "arena piena"); return nullptr; }
    *n = (enodo_t){.tipo = EN_BIN, .sx = sx, .dx = dx}; snprintf(n->op, sizeof(n->op), "%s", op); return n;
}

static enodo_t *p_or(parser_t *p);

static enodo_t *p_prim(parser_t *p) {
    salta(p); size_t col = p->pos + 1; char c = p->s[p->pos];
    if (c == '(') {
        ++p->pos; if (++p->prof > 16) { imp_err(p, col, "profondita eccessiva"); return nullptr; }
        enodo_t *e = p_or(p); --p->prof; if (p->err) { return nullptr; }
        salta(p); if (p->s[p->pos] != ')') { imp_err(p, p->pos + 1, "attesa ')'"); return nullptr; }
        ++p->pos; return e;
    }
    if (isdigit((unsigned char)c)) {
        int64_t v = 0;
        while (isdigit((unsigned char)p->s[p->pos])) {
            int64_t d = (int64_t)(p->s[p->pos++] - '0');
            if (ckd_mul(&v, v, 10) || ckd_add(&v, v, d)) { imp_err(p, col, "overflow intero"); return nullptr; }
        }
        enodo_t *n = a_alloca(p->a, sizeof(*n)); if (!n) { imp_err(p, col, "arena piena"); return nullptr; }
        *n = (enodo_t){.tipo = EN_INT, .val_int = v}; return n;
    }
    if (isalpha((unsigned char)c) || c == '_') {
        size_t ini = p->pos; while (isalnum((unsigned char)p->s[p->pos]) || p->s[p->pos] == '_') { ++p->pos; }
        size_t len = p->pos - ini;
        if ((len == 4 && strncmp(p->s + ini, "true", 4) == 0) || (len == 5 && strncmp(p->s + ini, "false", 5) == 0)) {
            enodo_t *n = a_alloca(p->a, sizeof(*n)); if (!n) { imp_err(p, col, "arena piena"); return nullptr; }
            *n = (enodo_t){.tipo = EN_BOOL, .val_bool = (len == 4)}; return n;
        }
        salta(p);
        if (p->s[p->pos] == '(') {
            ++p->pos; enodo_arg_t *testa = nullptr, **coda = &testa;
            salta(p);
            if (p->s[p->pos] != ')') {
                while (true) {
                    enodo_t *arg = p_or(p); if (p->err) { return nullptr; }
                    enodo_arg_t *el = a_alloca(p->a, sizeof(*el)); if (!el) { imp_err(p, p->pos + 1, "arena piena"); return nullptr; }
                    *el = (enodo_arg_t){.expr = arg, .prox = nullptr}; *coda = el; coda = &el->prox;
                    salta(p); if (p->s[p->pos] == ',') { ++p->pos; continue; } break;
                }
            }
            if (p->s[p->pos] != ')') { imp_err(p, p->pos + 1, "attesa ')'"); return nullptr; }
            ++p->pos;
            enodo_t *n = a_alloca(p->a, sizeof(*n)); if (!n) { imp_err(p, col, "arena piena"); return nullptr; }
            *n = (enodo_t){.tipo = EN_CALL, .nome = p->s + ini, .nome_len = len, .args = testa}; return n;
        }
        enodo_t *n = a_alloca(p->a, sizeof(*n)); if (!n) { imp_err(p, col, "arena piena"); return nullptr; }
        *n = (enodo_t){.tipo = EN_VAR, .nome = p->s + ini, .nome_len = len}; return n;
    }
    imp_err(p, col, "espressione inattesa"); return nullptr;
}
static enodo_t *p_un(parser_t *p) {
    salta(p); char c = p->s[p->pos];
    if ((c == '-' || (c == '!' && p->s[p->pos + 1] != '='))) {
        size_t col = p->pos + 1; ++p->pos;
        if (++p->prof > 16) { imp_err(p, col, "profondita eccessiva"); return nullptr; }
        enodo_t *x = p_un(p); --p->prof; if (p->err) { return nullptr; }
        enodo_t *n = a_alloca(p->a, sizeof(*n)); if (!n) { imp_err(p, col, "arena piena"); return nullptr; }
        *n = (enodo_t){.tipo = EN_UN, .sx = x}; n->op[0] = c; n->op[1] = '\0'; return n;
    }
    return p_prim(p);
}
static enodo_t *p_mul(parser_t *p) {
    enodo_t *e = p_un(p);
    while (!p->err) {
        salta(p); char c = p->s[p->pos];
        if (c == '*' || c == '/' || c == '%') { char op[2] = {c, '\0'}; ++p->pos; e = mk_bin(p, op, e, p_un(p)); }
        else { break; }
    }
    return e;
}
static enodo_t *p_add(parser_t *p) {
    enodo_t *e = p_mul(p);
    while (!p->err) {
        salta(p); char c = p->s[p->pos];
        if (c == '+' || c == '-') { char op[2] = {c, '\0'}; ++p->pos; e = mk_bin(p, op, e, p_mul(p)); }
        else { break; }
    }
    return e;
}
static enodo_t *p_cmp(parser_t *p) {
    enodo_t *e = p_add(p);
    while (!p->err) {
        if (match2(p, '<', '=')) { e = mk_bin(p, "<=", e, p_add(p)); }
        else if (match2(p, '>', '=')) { e = mk_bin(p, ">=", e, p_add(p)); }
        else if (match1_noeq(p, '<')) { e = mk_bin(p, "<", e, p_add(p)); }
        else if (match1_noeq(p, '>')) { e = mk_bin(p, ">", e, p_add(p)); }
        else { break; }
    }
    return e;
}
static enodo_t *p_eq(parser_t *p) {
    enodo_t *e = p_cmp(p);
    while (!p->err) {
        if (match2(p, '=', '=')) { e = mk_bin(p, "==", e, p_cmp(p)); }
        else if (match2(p, '!', '=')) { e = mk_bin(p, "!=", e, p_cmp(p)); }
        else { break; }
    }
    return e;
}
static enodo_t *p_and(parser_t *p) { enodo_t *e = p_eq(p); while (!p->err && match2(p, '&', '&')) { e = mk_bin(p, "&&", e, p_eq(p)); } return e; }
static enodo_t *p_or(parser_t *p) { enodo_t *e = p_and(p); while (!p->err && match2(p, '|', '|')) { e = mk_bin(p, "||", e, p_and(p)); } return e; }

enodo_t *parse_espressione_riga(expr_arena_t *a, const char *src, size_t *err_col, char *err_msg, size_t err_cap) {
    parser_t p = {.a = a, .s = src, .err_msg = err_msg, .err_cap = err_cap};
    enodo_t *rad = p_or(&p);
    if (!p.err) { salta(&p); if (p.s[p.pos] != '\0') { imp_err(&p, p.pos + 1, "token inatteso"); } }
    if (p.err) { *err_col = p.err_col; return nullptr; }
    return rad;
}

void stampa_sexpr(const enodo_t *n) {
    if (n->tipo == EN_INT) { printf("%" PRId64, n->val_int); }
    else if (n->tipo == EN_BOOL) { printf("%s", n->val_bool ? "true" : "false"); }
    else if (n->tipo == EN_VAR) { printf("%.*s", (int)n->nome_len, n->nome); }
    else if (n->tipo == EN_UN) { printf("(%s ", n->op); stampa_sexpr(n->sx); printf(")"); }
    else if (n->tipo == EN_BIN) { printf("(%s ", n->op); stampa_sexpr(n->sx); printf(" "); stampa_sexpr(n->dx); printf(")"); }
    else { printf("(call %.*s", (int)n->nome_len, n->nome); for (const enodo_arg_t *g = n->args; g; g = g->prox) { printf(" "); stampa_sexpr(g->expr); } printf(")"); }
}

