#include "tabella_hash.h"
#include <stdlib.h>
#include <string.h>

typedef struct nodo_ht { void *chiave, *valore; uint64_t hash; struct nodo_ht *prox; } nodo_ht_t;
struct tabella_hash { nodo_ht_t **secchi; size_t cap, len; ht_hash_fn hash; ht_uguali_fn uguali; ht_distruggi_fn dc, dv; };

static bool ht_rehash(tabella_hash_t *t, size_t ncap) {
    if (ncap == 0 || ncap > SIZE_MAX / sizeof(*t->secchi)) { return false; }
    nodo_ht_t **ns = malloc(ncap * sizeof(*ns)); if (!ns) { return false; }
    for (size_t i = 0; i < ncap; ++i) { ns[i] = nullptr; }
    for (size_t i = 0; i < t->cap; ++i) {
        for (nodo_ht_t *c = t->secchi[i], *p; c; c = p) { p = c->prox; size_t k = (size_t)(c->hash % ncap); c->prox = ns[k]; ns[k] = c; }
    }
    free(t->secchi); t->secchi = ns; t->cap = ncap; return true;
}
tabella_hash_t *ht_crea(const ht_config_t *cfg) {
    if (!cfg || !cfg->hash || !cfg->uguali) { return nullptr; }
    size_t cap = cfg->cap_iniziale ? cfg->cap_iniziale : 8;
    tabella_hash_t *t = malloc(sizeof(*t)); if (!t) { return nullptr; }
    t->secchi = malloc(cap * sizeof(*t->secchi)); if (!t->secchi) { free(t); return nullptr; }
    for (size_t i = 0; i < cap; ++i) { t->secchi[i] = nullptr; }
    t->cap = cap; t->len = 0; t->hash = cfg->hash; t->uguali = cfg->uguali; t->dc = cfg->d_chiave; t->dv = cfg->d_valore;
    return t;
}
void ht_distruggi(tabella_hash_t *t) {
    if (!t) { return; }
    for (size_t i = 0; i < t->cap; ++i) {
        for (nodo_ht_t *c = t->secchi[i], *p; c; c = p) { p = c->prox; if (t->dc) { t->dc(c->chiave); } if (t->dv) { t->dv(c->valore); } free(c); }
    }
    free(t->secchi); free(t);
}
int ht_inserisci(tabella_hash_t *t, void *chiave, void *valore) {
    if (!t || !chiave) { return -1; }
    uint64_t h = t->hash(chiave); size_t k = (size_t)(h % t->cap);
    for (nodo_ht_t *c = t->secchi[k]; c; c = c->prox) {
        if (c->hash == h && t->uguali(c->chiave, chiave)) {
            if (t->dv && c->valore != valore) { t->dv(c->valore); }
            c->valore = valore;
            if (t->dc && c->chiave != chiave) { t->dc(chiave); }
            return 0;
        }
    }
    if ((t->len + 1) * 4 > t->cap * 3) { if (!ht_rehash(t, t->cap * 2)) { return -1; } k = (size_t)(h % t->cap); }
    nodo_ht_t *n = malloc(sizeof(*n)); if (!n) { return -1; }
    *n = (nodo_ht_t){.chiave = chiave, .valore = valore, .hash = h, .prox = t->secchi[k]};
    t->secchi[k] = n; ++t->len; return 1;
}
void *ht_cerca(const tabella_hash_t *t, const void *chiave) {
    if (!t || !chiave) { return nullptr; }
    uint64_t h = t->hash(chiave); size_t k = (size_t)(h % t->cap);
    for (const nodo_ht_t *c = t->secchi[k]; c; c = c->prox) { if (c->hash == h && t->uguali(c->chiave, chiave)) { return c->valore; } }
    return nullptr;
}
uint64_t ht_hash_stringa(const void *chiave) {
    uint64_t h = 14695981039346656037ULL;
    for (const unsigned char *p = chiave; *p != '\0'; ++p) { h ^= (uint64_t)(*p); h *= 1099511628211ULL; }
    return h;
}
bool ht_uguali_stringa(const void *a, const void *b) { return strcmp(a, b) == 0; }

