#include <inttypes.h>
#include <stdckdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "tabella_hash.h"

typedef enum val_tipo { V_INT, V_BOOL } val_tipo_t;
typedef struct val { val_tipo_t tipo; union { int64_t i; bool b; } d; } val_t;
typedef struct env { tabella_hash_t *tab; struct env *genitore; size_t prof; } env_t;

static env_t *env_crea(env_t *gen) {
    env_t *e = malloc(sizeof(*e)); if (!e) { return nullptr; }
    e->tab = ht_crea(&(ht_config_t){.cap_iniziale = 4, .hash = ht_hash_stringa, .uguali = ht_uguali_stringa, .d_chiave = free, .d_valore = free});
    if (!e->tab) { free(e); return nullptr; }
    e->genitore = gen; e->prof = gen ? (gen->prof + 1) : 0; return e;
}
static void env_distruggi_catena(env_t *e) { while (e) { env_t *g = e->genitore; ht_distruggi(e->tab); free(e); e = g; } }
static val_t *env_get(const env_t *e, const char *nome) {
    for (; e; e = e->genitore) { val_t *v = ht_cerca(e->tab, nome); if (v) { return v; } }
    return nullptr;
}
static bool parsa_val(const char *s, val_t *out) {
    if (strcmp(s, "true") == 0) { *out = (val_t){.tipo = V_BOOL, .d.b = true}; return true; }
    if (strcmp(s, "false") == 0) { *out = (val_t){.tipo = V_BOOL, .d.b = false}; return true; }
    long long x = 0; char ex = '\0';
    if (sscanf(s, "%lld %c", &x, &ex) == 1) { *out = (val_t){.tipo = V_INT, .d.i = (int64_t)x}; return true; }
    return false;
}

int main(void) {
    env_t *cur = env_crea(nullptr); if (!cur) { return EXIT_FAILURE; }
    char riga[256], cmd[24], nome[48], tok[48], ex = '\0';
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%23s", cmd) != 1) { continue; }
        long long a = 0, b = 0; val_t v = {};
        if (strcmp(cmd, "ENTER") == 0) {
            env_t *figlio = env_crea(cur); if (!figlio) { env_distruggi_catena(cur); return EXIT_FAILURE; }
            cur = figlio; printf("ENTER prof=%zu\n", cur->prof);
        } else if (strcmp(cmd, "LEAVE") == 0) {
            if (!cur->genitore) { printf("LEAVE: ERRORE_GLOBALE\n"); }
            else { env_t *g = cur->genitore; ht_distruggi(cur->tab); free(cur); cur = g; printf("LEAVE prof=%zu\n", cur->prof); }
        } else if (strcmp(cmd, "DEF") == 0 && sscanf(riga, "DEF %47s %47s %c", nome, tok, &ex) == 2 && parsa_val(tok, &v)) {
            if (ht_cerca(cur->tab, nome)) { printf("DEF %s: GIA_DEFINITA\n", nome); }
            else {
                char *k = strdup(nome); val_t *vp = malloc(sizeof(*vp));
                if (!k || !vp) { free(k); free(vp); env_distruggi_catena(cur); return EXIT_FAILURE; }
                *vp = v; if (ht_inserisci(cur->tab, k, vp) < 0) { free(k); free(vp); env_distruggi_catena(cur); return EXIT_FAILURE; }
                printf("DEF %s: OK\n", nome);
            }
        } else if (strcmp(cmd, "SET") == 0 && sscanf(riga, "SET %47s %47s %c", nome, tok, &ex) == 2 && parsa_val(tok, &v)) {
            val_t *es = env_get(cur, nome);
            if (!es) { printf("SET %s: NON_DICHIARATA\n", nome); } else { *es = v; printf("SET %s: OK\n", nome); }
        } else if (strcmp(cmd, "GET") == 0 && sscanf(riga, "GET %47s %c", nome, &ex) == 1) {
            val_t *es = env_get(cur, nome);
            if (!es) { printf("GET %s: NON_DICHIARATA\n", nome); }
            else if (es->tipo == V_INT) { printf("GET %s: %" PRId64 "\n", nome, es->d.i); }
            else { printf("GET %s: %s\n", nome, es->d.b ? "true" : "false"); }
        } else if (strcmp(cmd, "ADD") == 0 && sscanf(riga, "ADD %lld %lld %c", &a, &b, &ex) == 2) {
            int64_t r = 0; if (ckd_add(&r, (int64_t)a, (int64_t)b)) { printf("ADD: OVERFLOW\n"); } else { printf("ADD: %" PRId64 "\n", r); }
        } else if (strcmp(cmd, "DIV") == 0 && sscanf(riga, "DIV %lld %lld %c", &a, &b, &ex) == 2) {
            if (b == 0) { printf("DIV: DIV_ZERO\n"); } else if ((int64_t)a == INT64_MIN && b == -1) { printf("DIV: OVERFLOW\n"); }
            else { printf("DIV: %" PRId64 "\n", (int64_t)a / (int64_t)b); }
        } else if (strcmp(cmd, "SHORT_AND") == 0 && sscanf(riga, "SHORT_AND %47s %lld %lld %c", nome, &a, &b, &ex) == 3) {
            val_t *es = env_get(cur, nome);
            if (!es || es->tipo != V_BOOL) { printf("SHORT_AND: ERR_TIPO\n"); }
            else if (!es->d.b) { printf("SHORT_AND: false (corto_circuito)\n"); }
            else if (b == 0) { printf("SHORT_AND: DIV_ZERO\n"); }
            else if ((int64_t)a == INT64_MIN && b == -1) { printf("SHORT_AND: OVERFLOW\n"); }
            else { printf("SHORT_AND: %s\n", ((int64_t)a / (int64_t)b > 0) ? "true" : "false"); }
        } else { env_distruggi_catena(cur); return EXIT_FAILURE; }
    }
    env_distruggi_catena(cur);
    return EXIT_SUCCESS;
}

