#include "builtin.h"
#include <stdckdint.h>
#include <stdio.h>
#include <string.h>

static bool err_fmt(char *err, size_t cap, const char *m) { snprintf(err, cap, "%s", m); return false; }

static bool fn_abs(const val_t *a, size_t n, val_t *out, char *err, size_t cap) {
    (void)n;
    if (a[0].tipo != VT_INT) { return err_fmt(err, cap, "tipo errato"); }
    if (a[0].d.i == INT64_MIN) { return err_fmt(err, cap, "overflow abs"); }
    *out = (val_t){.tipo = VT_INT, .d.i = (a[0].d.i < 0) ? -a[0].d.i : a[0].d.i};
    return true;
}
static bool fn_min(const val_t *a, size_t n, val_t *out, char *err, size_t cap) {
    (void)n;
    if (a[0].tipo != VT_INT || a[1].tipo != VT_INT) { return err_fmt(err, cap, "tipo errato"); }
    *out = (val_t){.tipo = VT_INT, .d.i = (a[0].d.i < a[1].d.i) ? a[0].d.i : a[1].d.i};
    return true;
}
static bool fn_max(const val_t *a, size_t n, val_t *out, char *err, size_t cap) {
    (void)n;
    if (a[0].tipo != VT_INT || a[1].tipo != VT_INT) { return err_fmt(err, cap, "tipo errato"); }
    *out = (val_t){.tipo = VT_INT, .d.i = (a[0].d.i > a[1].d.i) ? a[0].d.i : a[1].d.i};
    return true;
}
static bool fn_pot(const val_t *a, size_t n, val_t *out, char *err, size_t cap) {
    (void)n;
    if (a[0].tipo != VT_INT || a[1].tipo != VT_INT) { return err_fmt(err, cap, "tipo errato"); }
    if (a[1].d.i < 0) { return err_fmt(err, cap, "esponente negativo"); }
    int64_t ris = 1, base = a[0].d.i, esp = a[1].d.i;
    for (int64_t i = 0; i < esp; ++i) {
        if (ckd_mul(&ris, ris, base)) { return err_fmt(err, cap, "overflow pot"); }
    }
    *out = (val_t){.tipo = VT_INT, .d.i = ris};
    return true;
}
static bool fn_pari(const val_t *a, size_t n, val_t *out, char *err, size_t cap) {
    (void)n;
    if (a[0].tipo != VT_INT) { return err_fmt(err, cap, "tipo errato"); }
    *out = (val_t){.tipo = VT_BOOL, .d.b = (a[0].d.i % 2 == 0)};
    return true;
}

bool builtin_chiama(const char *nome, const val_t *args, size_t n, val_t *out, char *err, size_t cap) {
    static const builtin_voce_t TAB[] = {
        {"abs", 1, fn_abs}, {"min", 2, fn_min}, {"max", 2, fn_max}, {"pot", 2, fn_pot}, {"pari", 1, fn_pari}
    };
    for (size_t i = 0; i < sizeof(TAB) / sizeof(TAB[0]); ++i) {
        if (strcmp(TAB[i].nome, nome) == 0) {
            if (n != TAB[i].arita) { return err_fmt(err, cap, "arita errata"); }
            return TAB[i].fn(args, n, out, err, cap);
        }
    }
    return err_fmt(err, cap, "funzione sconosciuta");
}

