#include <string.h>
#include "builtin.h"

typedef struct cornice { int64_t arg; size_t prof; } cornice_t;
typedef struct stats_ric { size_t create, liberate, max_prof; } stats_ric_t;

static int fact_ric(int64_t n, size_t prof, stats_ric_t *st, int64_t *out) {
    cornice_t *c = malloc(sizeof(*c));
    if (!c) { return -3; }
    *c = (cornice_t){.arg = n, .prof = prof}; ++st->create;
    int esito = 0;
    if (prof > st->max_prof) { esito = -1; }
    else if (n <= 1) { *out = 1; }
    else {
        int64_t sub = 0;
        esito = fact_ric(n - 1, prof + 1, st, &sub);
        if (esito == 0 && ckd_mul(out, c->arg, sub)) { esito = -2; }
    }
    free(c); ++st->liberate;
    return esito;
}

static bool parsa_arg(const char *s, val_t *out) {
    if (strcmp(s, "true") == 0) { *out = (val_t){.tipo = VT_BOOL, .d.b = true}; return true; }
    if (strcmp(s, "false") == 0) { *out = (val_t){.tipo = VT_BOOL, .d.b = false}; return true; }
    long long v = 0; char ex = '\0';
    if (sscanf(s, "%lld %c", &v, &ex) == 1) { *out = (val_t){.tipo = VT_INT, .d.i = (int64_t)v}; return true; }
    return false;
}

int main(void) {
    char riga[256], cmd[24], nome[32];
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%23s", cmd) != 1) { continue; }
        if (strcmp(cmd, "CALL") == 0) {
            size_t na = 0; int pos = 0;
            if (sscanf(riga, "CALL %31s %zu%n", nome, &na, &pos) != 2 || na > 4) { return EXIT_FAILURE; }
            val_t args[4] = {}; const char *p = riga + pos;
            for (size_t i = 0; i < na; ++i) {
