            } else { printf("CALL %s: ERRORE (%s)\n", nome, err); }
        } else if (strcmp(cmd, "FACT") == 0) {
            long long n = 0; size_t mp = 0; char ex = '\0';
            if (sscanf(riga, "FACT %lld %zu %c", &n, &mp, &ex) != 2) { return EXIT_FAILURE; }
            if (n < 0) { printf("FACT(%lld): ERR_ARG (cornici=0/0)\n", n); continue; }
            stats_ric_t st = {.max_prof = mp}; int64_t ris = 0;
            int e = fact_ric((int64_t)n, 1, &st, &ris);
            if (e == 0) { printf("FACT(%lld): %" PRId64 " (cornici=%zu/%zu)\n", n, ris, st.liberate, st.create); }
            else if (e == -1) { printf("FACT(%lld): ERR_PROFONDITA (cornici=%zu/%zu)\n", n, st.liberate, st.create); }
            else { printf("FACT(%lld): ERR_OVERFLOW (cornici=%zu/%zu)\n", n, st.liberate, st.create); }
        } else if (strcmp(cmd, "WHILE_SUM") == 0) {
            long long n = 0; size_t mp = 0; char ex = '\0';
            if (sscanf(riga, "WHILE_SUM %lld %zu %c", &n, &mp, &ex) != 2 || n < 0) { return EXIT_FAILURE; }
            int64_t i = 1, somma = 0; size_t passi = 0; int err = 0;
            while (i <= (int64_t)n) {
                if (passi >= mp) { err = 1; break; }
                ++passi;
                if (ckd_add(&somma, somma, i)) { err = 2; break; }
                ++i;
            }
            if (err == 0) { printf("WHILE_SUM(%lld): %" PRId64 " (passi=%zu)\n", n, somma, passi); }
            else if (err == 1) { printf("WHILE_SUM(%lld): ERR_PASSI (passi=%zu)\n", n, passi); }
            else { printf("WHILE_SUM(%lld): ERR_OVERFLOW (passi=%zu)\n", n, passi); }
        } else { return EXIT_FAILURE; }
    }
    return EXIT_SUCCESS;
}

