soluzione_file.arena.c:
#include "arena.h"
#include <stdckdint.h>
#include <stdlib.h>
#include <string.h>

bool arena_crea(arena_t *a, size_t cap) {
    if (a == nullptr || cap == 0) {
        return false;
    }
    a->buf = malloc(cap);
    if (a->buf == nullptr) {
        return false;
    }
    a->cap = cap;
    a->usati = 0;
    return true;
}

void arena_distruggi(arena_t *a) {
    if (a != nullptr) {
        free(a->buf);
        a->buf = nullptr;
        a->cap = 0;
        a->usati = 0;
    }
}

void *arena_alloca(arena_t *a, size_t dim) {
    if (a == nullptr || a->buf == nullptr || dim == 0) {
        return nullptr;
    }
    size_t allin = alignof(max_align_t);
    size_t somma = 0, fine = 0;
    if (ckd_add(&somma, a->usati, allin - 1)) {
        return nullptr;
    }
    size_t ini = somma & ~(allin - 1);
    if (ckd_add(&fine, ini, dim) || fine > a->cap) {
        return nullptr;
    }
    a->usati = fine;
    return a->buf + ini;
}

char *arena_copia_str(arena_t *a, const char *s, size_t len) {
    size_t tot = 0;
    if (ckd_add(&tot, len, 1)) {
        return nullptr;
    }
    char *dst = arena_alloca(a, tot);
    if (dst == nullptr) {
        return nullptr;
    }
    if (len > 0) {
        memcpy(dst, s, len);
    }
    dst[len] = '\0';
    return dst;
}

