    TOK_VAR, TOK_IF, TOK_ELSE, TOK_WHILE, TOK_FN, TOK_RETURN, TOK_STAMPA, TOK_TRUE, TOK_FALSE,
    TOK_PIU, TOK_MENO, TOK_PER, TOK_DIV, TOK_MOD, TOK_BANG,
    TOK_ASS, TOK_EQ, TOK_NEQ, TOK_LT, TOK_LE, TOK_GT, TOK_GE, TOK_AND, TOK_OR,
    TOK_TONDA_A, TOK_TONDA_C, TOK_GRAFFA_A, TOK_GRAFFA_C, TOK_VIRG, TOK_PV
} tok_tipo_t;

typedef struct token {
    tok_tipo_t tipo;
    const char *inizio;
