soluzione_file.lexer.c:
#include "lexer.h"
#include <ctype.h>
#include <stdckdint.h>
#include <string.h>

void lexer_init(lexer_t *lx, const char *src) {
    *lx = (lexer_t){.src = src, .pos = 0, .riga = 1, .col = 1};
}

static char avanza(lexer_t *lx) {
    char c = lx->src[lx->pos++];
    if (c == '\n') { ++lx->riga; lx->col = 1; } else { ++lx->col; }
    return c;
}

static void salta_spazi(lexer_t *lx) {
    while (true) {
        char c = lx->src[lx->pos];
        if (c != '\0' && isspace((unsigned char)c)) {
            avanza(lx);
        } else if (c == '/' && lx->src[lx->pos + 1] == '/') {
            while (lx->src[lx->pos] != '\0' && lx->src[lx->pos] != '\n') { avanza(lx); }
        } else {
            break;
        }
    }
}

static tok_tipo_t cerca_kw(const char *s, size_t n) {
    static const struct { const char *kw; tok_tipo_t t; } KW[] = {
        {"var", TOK_VAR}, {"if", TOK_IF}, {"else", TOK_ELSE}, {"while", TOK_WHILE},
        {"fn", TOK_FN}, {"return", TOK_RETURN}, {"stampa", TOK_STAMPA}, {"true", TOK_TRUE}, {"false", TOK_FALSE}
    };
    for (size_t i = 0; i < sizeof(KW) / sizeof(KW[0]); ++i) {
        if (strlen(KW[i].kw) == n && strncmp(s, KW[i].kw, n) == 0) { return KW[i].t; }
    }
    return TOK_IDENT;
}

token_t lexer_prossimo(lexer_t *lx) {
    salta_spazi(lx);
    size_t r = lx->riga, col = lx->col, start = lx->pos;
    char c = lx->src[lx->pos];
    if (c == '\0') { return (token_t){.tipo = TOK_EOF, .riga = r, .col = col}; }
    if (isalpha((unsigned char)c) || c == '_') {
        while (isalnum((unsigned char)lx->src[lx->pos]) || lx->src[lx->pos] == '_') { avanza(lx); }
        size_t n = lx->pos - start;
        return (token_t){.tipo = cerca_kw(lx->src + start, n), .inizio = lx->src + start, .len = n, .riga = r, .col = col};
    }
    if (isdigit((unsigned char)c)) {
        int64_t val = 0; bool ovf = false;
        while (isdigit((unsigned char)lx->src[lx->pos])) {
            int64_t d = (int64_t)(avanza(lx) - '0');
            if (!ovf && (ckd_mul(&val, val, 10) || ckd_add(&val, val, d))) { ovf = true; }
        }
        if (ovf) { return (token_t){.tipo = TOK_ERR, .inizio = "overflow intero", .riga = r, .col = col}; }
        return (token_t){.tipo = TOK_INT, .inizio = lx->src + start, .len = lx->pos - start, .val_int = val, .riga = r, .col = col};
    }
    avanza(lx);
    char p = lx->src[lx->pos];
    if (c == '=' && p == '=') { avanza(lx); return (token_t){.tipo = TOK_EQ, .riga = r, .col = col}; }
    if (c == '!' && p == '=') { avanza(lx); return (token_t){.tipo = TOK_NEQ, .riga = r, .col = col}; }
    if (c == '<' && p == '=') { avanza(lx); return (token_t){.tipo = TOK_LE, .riga = r, .col = col}; }
    if (c == '>' && p == '=') { avanza(lx); return (token_t){.tipo = TOK_GE, .riga = r, .col = col}; }
    if (c == '&' && p == '&') { avanza(lx); return (token_t){.tipo = TOK_AND, .riga = r, .col = col}; }
    if (c == '|' && p == '|') { avanza(lx); return (token_t){.tipo = TOK_OR, .riga = r, .col = col}; }
    tok_tipo_t st = TOK_ERR;
    switch (c) {
        case '+': st = TOK_PIU; break; case '-': st = TOK_MENO; break; case '*': st = TOK_PER; break;
        case '/': st = TOK_DIV; break; case '%': st = TOK_MOD; break; case '!': st = TOK_BANG; break;
        case '=': st = TOK_ASS; break; case '<': st = TOK_LT; break; case '>': st = TOK_GT; break;
        case '(': st = TOK_TONDA_A; break; case ')': st = TOK_TONDA_C; break;
        case '{': st = TOK_GRAFFA_A; break; case '}': st = TOK_GRAFFA_C; break;
        case ',': st = TOK_VIRG; break; case ';': st = TOK_PV; break;
        default: return (token_t){.tipo = TOK_ERR, .inizio = "carattere non valido", .riga = r, .col = col};
    }
    return (token_t){.tipo = st, .riga = r, .col = col};
}

