#include "parser.h"
#include "lexer.h"

static constexpr size_t MAX_PROF_PARSE = 32;

typedef struct parser {
    arena_t *a;
    lexer_t lx;
    token_t cur;
    token_t prox;
    size_t prof;
    errore_t *err;
} parser_t;

static void avanza(parser_t *p) {
    p->cur = p->prox;
    if (p->cur.tipo == TOK_ERR) {
        errore_imposta(p->err, p->cur.riga, p->cur.col, p->cur.inizio);
    }
    p->prox = lexer_prossimo(&p->lx);
}

static bool accetta(parser_t *p, tok_tipo_t t) {
    if (p->cur.tipo == t) { avanza(p); return true; }
    return false;
}

static bool attendi(parser_t *p, tok_tipo_t t, const char *msg) {
    if (p->cur.tipo == t) { avanza(p); return true; }
    errore_imposta(p->err, p->cur.riga, p->cur.col, msg);
    return false;
}

static nodo_t *nuovo_nodo(parser_t *p, ast_tipo_t tipo, size_t r, size_t c) {
    nodo_t *n = arena_alloca(p->a, sizeof(*n));
    if (n == nullptr) {
        errore_imposta(p->err, r, c, "arena AST esaurita");
        return nullptr;
    }
    *n = (nodo_t){.tipo = tipo, .riga = r, .col = c};
    return n;
}

static nodo_t *p_expr(parser_t *p);
static nodo_t *p_stmt(parser_t *p);

static nodo_t *p_blocco(parser_t *p) {
    size_t r = p->cur.riga, c = p->cur.col;
    if (!attendi(p, TOK_GRAFFA_A, "attesa '{'")) { return nullptr; }
    nodo_t *b = nuovo_nodo(p, AST_BLOCCO, r, c);
    if (b == nullptr) { return nullptr; }
    nodo_t **coda = &b->d.lista;
    while (!p->err->attivo && p->cur.tipo != TOK_GRAFFA_C && p->cur.tipo != TOK_EOF) {
        nodo_t *st = p_stmt(p);
        if (st == nullptr) { return nullptr; }
        *coda = st;
        coda = &st->prox;
    }
    if (!attendi(p, TOK_GRAFFA_C, "attesa '}'")) { return nullptr; }
    return b;
}

static nodo_t *p_prim(parser_t *p) {
    token_t t = p->cur;
    if (t.tipo == TOK_INT) {
        avanza(p);
        nodo_t *n = nuovo_nodo(p, AST_INT, t.riga, t.col);
        if (n != nullptr) { n->d.val_int = t.val_int; }
        return n;
    }
    if (t.tipo == TOK_TRUE || t.tipo == TOK_FALSE) {
        avanza(p);
        nodo_t *n = nuovo_nodo(p, AST_BOOL, t.riga, t.col);
        if (n != nullptr) { n->d.val_bool = (t.tipo == TOK_TRUE); }
        return n;
    }
    if (t.tipo == TOK_IDENT) {
        avanza(p);
        char *nome = arena_copia_str(p->a, t.inizio, t.len);
        if (nome == nullptr) { errore_imposta(p->err, t.riga, t.col, "arena AST esaurita"); return nullptr; }
        if (accetta(p, TOK_TONDA_A)) {
            nodo_t *n = nuovo_nodo(p, AST_CHIAMATA, t.riga, t.col);
            if (n == nullptr) { return nullptr; }
            n->d.chiamata.nome = nome;
            arg_t **coda = &n->d.chiamata.args;
            if (p->cur.tipo != TOK_TONDA_C) {
                do {
                    nodo_t *e = p_expr(p);
                    if (e == nullptr) { return nullptr; }
                    arg_t *ag = arena_alloca(p->a, sizeof(*ag));
                    if (ag == nullptr) { errore_imposta(p->err, t.riga, t.col, "arena AST esaurita"); return nullptr; }
                    *ag = (arg_t){.expr = e, .prox = nullptr};
                    *coda = ag;
                    coda = &ag->prox;
                    ++n->d.chiamata.n_args;
                } while (accetta(p, TOK_VIRG));
            }
            if (!attendi(p, TOK_TONDA_C, "attesa ')'")) { return nullptr; }
            return n;
        }
        nodo_t *n = nuovo_nodo(p, AST_VAR, t.riga, t.col);
        if (n != nullptr) { n->d.nome = nome; }
        return n;
    }
    if (accetta(p, TOK_TONDA_A)) {
        if (++p->prof > MAX_PROF_PARSE) { errore_imposta(p->err, t.riga, t.col, "profondita parser eccessiva"); return nullptr; }
        nodo_t *e = p_expr(p);
        --p->prof;
        if (e == nullptr || !attendi(p, TOK_TONDA_C, "attesa ')'")) { return nullptr; }
        return e;
    }
    errore_imposta(p->err, t.riga, t.col, "espressione inattesa");
    return nullptr;
}

static nodo_t *p_un(parser_t *p) {
    token_t t = p->cur;
    if (t.tipo == TOK_MENO || t.tipo == TOK_BANG) {
        avanza(p);
        if (++p->prof > MAX_PROF_PARSE) { errore_imposta(p->err, t.riga, t.col, "profondita parser eccessiva"); return nullptr; }
        nodo_t *x = p_un(p);
        --p->prof;
        if (x == nullptr) { return nullptr; }
        nodo_t *n = nuovo_nodo(p, AST_UNARIO, t.riga, t.col);
        if (n != nullptr) { n->d.unario.op = (t.tipo == TOK_MENO) ? OP_NEG : OP_NOT; n->d.unario.x = x; }
        return n;
    }
    return p_prim(p);
}

static nodo_t *mk_bin(parser_t *p, op_tipo_t op, size_t r, size_t c, nodo_t *sx, nodo_t *dx) {
    if (sx == nullptr || dx == nullptr) { return nullptr; }
    nodo_t *n = nuovo_nodo(p, AST_BINARIO, r, c);
    if (n != nullptr) { n->d.binario.op = op; n->d.binario.sx = sx; n->d.binario.dx = dx; }
    return n;
}

static nodo_t *p_mul(parser_t *p) {
    nodo_t *e = p_un(p);
    while (!p->err->attivo && (p->cur.tipo == TOK_PER || p->cur.tipo == TOK_DIV || p->cur.tipo == TOK_MOD)) {
        token_t t = p->cur; avanza(p);
        op_tipo_t op = (t.tipo == TOK_PER) ? OP_PER : ((t.tipo == TOK_DIV) ? OP_DIV : OP_MOD);
        e = mk_bin(p, op, t.riga, t.col, e, p_un(p));
    }
    return e;
}

static nodo_t *p_add(parser_t *p) {
    nodo_t *e = p_mul(p);
    while (!p->err->attivo && (p->cur.tipo == TOK_PIU || p->cur.tipo == TOK_MENO)) {
        token_t t = p->cur; avanza(p);
        e = mk_bin(p, (t.tipo == TOK_PIU) ? OP_PIU : OP_MENO, t.riga, t.col, e, p_mul(p));
    }
    return e;
}

static nodo_t *p_cmp(parser_t *p) {
    nodo_t *e = p_add(p);
    while (!p->err->attivo && (p->cur.tipo == TOK_LT || p->cur.tipo == TOK_LE || p->cur.tipo == TOK_GT || p->cur.tipo == TOK_GE)) {
        token_t t = p->cur; avanza(p);
        op_tipo_t op = (t.tipo == TOK_LT) ? OP_LT : ((t.tipo == TOK_LE) ? OP_LE : ((t.tipo == TOK_GT) ? OP_GT : OP_GE));
        e = mk_bin(p, op, t.riga, t.col, e, p_add(p));
    }
    return e;
}

static nodo_t *p_eq(parser_t *p) {
    nodo_t *e = p_cmp(p);
    while (!p->err->attivo && (p->cur.tipo == TOK_EQ || p->cur.tipo == TOK_NEQ)) {
        token_t t = p->cur; avanza(p);
        e = mk_bin(p, (t.tipo == TOK_EQ) ? OP_EQ : OP_NEQ, t.riga, t.col, e, p_cmp(p));
    }
    return e;
}

static nodo_t *p_and(parser_t *p) {
    nodo_t *e = p_eq(p);
    while (!p->err->attivo && p->cur.tipo == TOK_AND) {
        token_t t = p->cur; avanza(p);
        e = mk_bin(p, OP_AND, t.riga, t.col, e, p_eq(p));
    }
    return e;
}

static nodo_t *p_expr(parser_t *p) {
    nodo_t *e = p_and(p);
    while (!p->err->attivo && p->cur.tipo == TOK_OR) {
        token_t t = p->cur; avanza(p);
        e = mk_bin(p, OP_OR, t.riga, t.col, e, p_and(p));
    }
    return e;
}

static nodo_t *p_stmt(parser_t *p) {
    token_t t = p->cur;
    if (accetta(p, TOK_VAR)) {
        token_t id = p->cur;
        if (!attendi(p, TOK_IDENT, "atteso nome variabile")) { return nullptr; }
        if (!attendi(p, TOK_ASS, "atteso '='")) { return nullptr; }
        nodo_t *e = p_expr(p);
        if (e == nullptr || !attendi(p, TOK_PV, "atteso ';'")) { return nullptr; }
        nodo_t *n = nuovo_nodo(p, AST_DECL_VAR, t.riga, t.col);
        char *nm = arena_copia_str(p->a, id.inizio, id.len);
        if (n == nullptr || nm == nullptr) { errore_imposta(p->err, t.riga, t.col, "arena AST esaurita"); return nullptr; }
        n->d.var_stmt.nome = nm; n->d.var_stmt.expr = e;
        return n;
    }
    if (accetta(p, TOK_STAMPA)) {
        nodo_t *e = p_expr(p);
        if (e == nullptr || !attendi(p, TOK_PV, "atteso ';'")) { return nullptr; }
        nodo_t *n = nuovo_nodo(p, AST_STAMPA, t.riga, t.col);
        if (n != nullptr) { n->d.expr = e; }
        return n;
    }
    if (accetta(p, TOK_IF)) {
        if (!attendi(p, TOK_TONDA_A, "attesa '('")) { return nullptr; }
        nodo_t *cond = p_expr(p);
        if (cond == nullptr || !attendi(p, TOK_TONDA_C, "attesa ')'")) { return nullptr; }
        nodo_t *rv = p_blocco(p);
        if (rv == nullptr) { return nullptr; }
        nodo_t *rf = nullptr;
        if (accetta(p, TOK_ELSE)) {
            rf = (p->cur.tipo == TOK_IF) ? p_stmt(p) : p_blocco(p);
            if (rf == nullptr) { return nullptr; }
        }
        nodo_t *n = nuovo_nodo(p, AST_IF, t.riga, t.col);
        if (n != nullptr) { n->d.sel.cond = cond; n->d.sel.ramo_v = rv; n->d.sel.ramo_f = rf; }
        return n;
    }
    if (accetta(p, TOK_WHILE)) {
        if (!attendi(p, TOK_TONDA_A, "attesa '('")) { return nullptr; }
        nodo_t *cond = p_expr(p);
        if (cond == nullptr || !attendi(p, TOK_TONDA_C, "attesa ')'")) { return nullptr; }
        nodo_t *corpo = p_blocco(p);
        if (corpo == nullptr) { return nullptr; }
        nodo_t *n = nuovo_nodo(p, AST_WHILE, t.riga, t.col);
        if (n != nullptr) { n->d.ciclo.cond = cond; n->d.ciclo.corpo = corpo; }
        return n;
    }
    if (accetta(p, TOK_FN)) {
        token_t id = p->cur;
        if (!attendi(p, TOK_IDENT, "atteso nome funzione")) { return nullptr; }
        if (!attendi(p, TOK_TONDA_A, "attesa '('")) { return nullptr; }
        nodo_t *n = nuovo_nodo(p, AST_FN, t.riga, t.col);
        char *nm = arena_copia_str(p->a, id.inizio, id.len);
        if (n == nullptr || nm == nullptr) { errore_imposta(p->err, t.riga, t.col, "arena AST esaurita"); return nullptr; }
        n->d.fn.nome = nm;
        param_t **coda = &n->d.fn.params;
        if (p->cur.tipo != TOK_TONDA_C) {
            do {
                token_t pid = p->cur;
                if (!attendi(p, TOK_IDENT, "atteso parametro")) { return nullptr; }
                param_t *pm = arena_alloca(p->a, sizeof(*pm));
                char *pnm = arena_copia_str(p->a, pid.inizio, pid.len);
                if (pm == nullptr || pnm == nullptr) { errore_imposta(p->err, pid.riga, pid.col, "arena AST esaurita"); return nullptr; }
                *pm = (param_t){.nome = pnm, .prox = nullptr};
                *coda = pm; coda = &pm->prox; ++n->d.fn.n_params;
            } while (accetta(p, TOK_VIRG));
        }
        if (!attendi(p, TOK_TONDA_C, "attesa ')'")) { return nullptr; }
        n->d.fn.corpo = p_blocco(p);
        return (n->d.fn.corpo != nullptr) ? n : nullptr;
    }
    if (accetta(p, TOK_RETURN)) {
        nodo_t *e = nullptr;
        if (p->cur.tipo != TOK_PV) {
            e = p_expr(p);
            if (e == nullptr) { return nullptr; }
        }
        if (!attendi(p, TOK_PV, "atteso ';'")) { return nullptr; }
        nodo_t *n = nuovo_nodo(p, AST_RETURN, t.riga, t.col);
        if (n != nullptr) { n->d.expr = e; }
        return n;
    }
    if (t.tipo == TOK_IDENT && p->prox.tipo == TOK_ASS) {
        avanza(p); avanza(p);
        nodo_t *e = p_expr(p);
        if (e == nullptr || !attendi(p, TOK_PV, "atteso ';'")) { return nullptr; }
        nodo_t *n = nuovo_nodo(p, AST_ASS, t.riga, t.col);
        char *nm = arena_copia_str(p->a, t.inizio, t.len);
        if (n == nullptr || nm == nullptr) { errore_imposta(p->err, t.riga, t.col, "arena AST esaurita"); return nullptr; }
        n->d.var_stmt.nome = nm; n->d.var_stmt.expr = e;
        return n;
    }
    nodo_t *e = p_expr(p);
    if (e == nullptr || !attendi(p, TOK_PV, "atteso ';'")) { return nullptr; }
    nodo_t *n = nuovo_nodo(p, AST_EXPR_STMT, t.riga, t.col);
    if (n != nullptr) { n->d.expr = e; }
    return n;
}

nodo_t *parse_programma(arena_t *arena, const char *sorgente, errore_t *err) {
    parser_t p = {.a = arena, .err = err};
    lexer_init(&p.lx, sorgente);
    p.prox = lexer_prossimo(&p.lx);
    avanza(&p);
    nodo_t *prog = nuovo_nodo(&p, AST_BLOCCO, 1, 1);
    if (prog == nullptr) { return nullptr; }
    nodo_t **coda = &prog->d.lista;
    while (!err->attivo && p.cur.tipo != TOK_EOF) {
        nodo_t *st = p_stmt(&p);
        if (st == nullptr) { return nullptr; }
        *coda = st;
        coda = &st->prox;
    }
    return err->attivo ? nullptr : prog;
}

