soluzione_file.eval.c:
#include "eval.h"
#include <stdckdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "arena.h"
#include "parser.h"
#include "tabella_hash.h"

static constexpr size_t MAX_PROF_CHIAMATE = 64;
static constexpr size_t MAX_PASSI = 10000;

typedef struct ambiente {
    tabella_hash_t *var;
    struct ambiente *genitore;
} ambiente_t;

typedef valore_t (*builtin_fn)(const valore_t *args, size_t n, size_t r, size_t c, errore_t *err);

typedef struct funzione {
    bool predefinita;
    size_t arita;
    union {
        const nodo_t *decl;
        builtin_fn fn;
    } d;
} funzione_t;

typedef struct stato_eval {
    ambiente_t *globale;
    tabella_hash_t *funzioni;
    out_buf_t *out;
    errore_t *err;
    size_t prof;
    size_t passi;
    bool in_ritorno;
    valore_t val_ritorno;
} stato_eval_t;

static ambiente_t *env_crea(ambiente_t *gen) {
    ambiente_t *e = malloc(sizeof(*e));
    if (e == nullptr) { return nullptr; }
    e->var = ht_crea(&(ht_config_t){.cap_iniziale = 8, .hash = ht_hash_stringa, .uguali = ht_uguali_stringa, .distruggi_chiave = free, .distruggi_valore = free});
    if (e->var == nullptr) { free(e); return nullptr; }
    e->genitore = gen;
    return e;
}

static void env_distruggi(ambiente_t *e) {
    if (e != nullptr) { ht_distruggi(e->var); free(e); }
}

static valore_t *env_cerca(const ambiente_t *e, const char *nome) {
    for (; e != nullptr; e = e->genitore) {
        valore_t *v = ht_cerca(e->var, nome);
        if (v != nullptr) { return v; }
    }
    return nullptr;
}

static bool env_def(ambiente_t *e, const char *nome, valore_t v, size_t r, size_t c, errore_t *err) {
    if (ht_cerca(e->var, nome) != nullptr) {
        errore_imposta(err, r, c, "variabile gia definita");
        return false;
    }
    char *k = strdup(nome);
    valore_t *vp = malloc(sizeof(*vp));
    if (k == nullptr || vp == nullptr) {
        free(k); free(vp);
        errore_imposta(err, r, c, "memoria esaurita");
        return false;
    }
    *vp = v;
    if (ht_inserisci(e->var, k, vp) < 0) {
        free(k); free(vp);
        errore_imposta(err, r, c, "memoria esaurita");
        return false;
    }
    return true;
}

static void out_appendi(out_buf_t *o, const char *s) {
    size_t n = strlen(s);
    if (o->len + n + 2 < sizeof(o->dati)) {
        memcpy(o->dati + o->len, s, n);
        o->len += n;
        o->dati[o->len++] = '\n';
        o->dati[o->len] = '\0';
    }
}

static valore_t bi_abs(const valore_t *a, size_t n, size_t r, size_t c, errore_t *err) {
    (void)n;
    if (a[0].tipo != VAL_INT) { errore_imposta(err, r, c, "abs richiede intero"); return val_nullo(); }
    if (a[0].d.i == INT64_MIN) { errore_imposta(err, r, c, "overflow intero"); return val_nullo(); }
    return val_int((a[0].d.i < 0) ? -a[0].d.i : a[0].d.i);
}

static valore_t bi_min(const valore_t *a, size_t n, size_t r, size_t c, errore_t *err) {
    (void)n;
    if (a[0].tipo != VAL_INT || a[1].tipo != VAL_INT) { errore_imposta(err, r, c, "min richiede interi"); return val_nullo(); }
    return val_int((a[0].d.i < a[1].d.i) ? a[0].d.i : a[1].d.i);
}

static valore_t bi_max(const valore_t *a, size_t n, size_t r, size_t c, errore_t *err) {
    (void)n;
    if (a[0].tipo != VAL_INT || a[1].tipo != VAL_INT) { errore_imposta(err, r, c, "max richiede interi"); return val_nullo(); }
    return val_int((a[0].d.i > a[1].d.i) ? a[0].d.i : a[1].d.i);
}

static valore_t bi_pot(const valore_t *a, size_t n, size_t r, size_t c, errore_t *err) {
    (void)n;
    if (a[0].tipo != VAL_INT || a[1].tipo != VAL_INT) { errore_imposta(err, r, c, "pot richiede interi"); return val_nullo(); }
    if (a[1].d.i < 0) { errore_imposta(err, r, c, "esponente negativo"); return val_nullo(); }
    int64_t ris = 1;
    for (int64_t i = 0; i < a[1].d.i; ++i) {
        if (ckd_mul(&ris, ris, a[0].d.i)) { errore_imposta(err, r, c, "overflow intero"); return val_nullo(); }
    }
    return val_int(ris);
}

static bool registra_builtin(tabella_hash_t *ft, const char *nome, size_t arita, builtin_fn fn) {
    char *k = strdup(nome);
    funzione_t *f = malloc(sizeof(*f));
    if (k == nullptr || f == nullptr) { free(k); free(f); return false; }
    *f = (funzione_t){.predefinita = true, .arita = arita, .d.fn = fn};
    if (ht_inserisci(ft, k, f) < 0) { free(k); free(f); return false; }
    return true;
}

static void esegui_blocco(stato_eval_t *st, const nodo_t *blocco, ambiente_t *env);

static valore_t valuta_expr(stato_eval_t *st, const nodo_t *n, ambiente_t *env) {
    if (st->err->attivo) { return val_nullo(); }
    switch (n->tipo) {
        case AST_INT: return val_int(n->d.val_int);
        case AST_BOOL: return val_bool(n->d.val_bool);
        case AST_VAR: {
            valore_t *v = env_cerca(env, n->d.nome);
            if (v == nullptr) { errore_imposta(st->err, n->riga, n->col, "variabile non dichiarata"); return val_nullo(); }
            return *v;
        }
        case AST_UNARIO: {
            valore_t x = valuta_expr(st, n->d.unario.x, env);
            if (st->err->attivo) { return val_nullo(); }
            if (n->d.unario.op == OP_NEG) {
                if (x.tipo != VAL_INT) { errore_imposta(st->err, n->riga, n->col, "tipo errato per '-'"); return val_nullo(); }
                if (x.d.i == INT64_MIN) { errore_imposta(st->err, n->riga, n->col, "overflow intero"); return val_nullo(); }
                return val_int(-x.d.i);
            }
            if (x.tipo != VAL_BOOL) { errore_imposta(st->err, n->riga, n->col, "tipo errato per '!'"); return val_nullo(); }
            return val_bool(!x.d.b);
        }
        case AST_BINARIO: {
            op_tipo_t op = n->d.binario.op;
            valore_t a = valuta_expr(st, n->d.binario.sx, env);
            if (st->err->attivo) { return val_nullo(); }
            if (op == OP_AND || op == OP_OR) {
                if (a.tipo != VAL_BOOL) { errore_imposta(st->err, n->riga, n->col, "operatore logico richiede bool"); return val_nullo(); }
                if (op == OP_AND && !a.d.b) { return val_bool(false); }
                if (op == OP_OR && a.d.b) { return val_bool(true); }
                valore_t b = valuta_expr(st, n->d.binario.dx, env);
                if (st->err->attivo) { return val_nullo(); }
                if (b.tipo != VAL_BOOL) { errore_imposta(st->err, n->riga, n->col, "operatore logico richiede bool"); return val_nullo(); }
                return val_bool(b.d.b);
            }
            valore_t b = valuta_expr(st, n->d.binario.dx, env);
            if (st->err->attivo) { return val_nullo(); }
            if (op == OP_EQ || op == OP_NEQ) {
                if (a.tipo != b.tipo) { errore_imposta(st->err, n->riga, n->col, "confronto tra tipi diversi"); return val_nullo(); }
                bool eq = (a.tipo == VAL_INT) ? (a.d.i == b.d.i) : ((a.tipo == VAL_BOOL) ? (a.d.b == b.d.b) : true);
                return val_bool((op == OP_EQ) ? eq : !eq);
            }
            if (a.tipo != VAL_INT || b.tipo != VAL_INT) { errore_imposta(st->err, n->riga, n->col, "operazione richiede interi"); return val_nullo(); }
            int64_t r = 0;
            if (op == OP_PIU) { if (ckd_add(&r, a.d.i, b.d.i)) { errore_imposta(st->err, n->riga, n->col, "overflow intero"); } return val_int(r); }
            if (op == OP_MENO) { if (ckd_sub(&r, a.d.i, b.d.i)) { errore_imposta(st->err, n->riga, n->col, "overflow intero"); } return val_int(r); }
            if (op == OP_PER) { if (ckd_mul(&r, a.d.i, b.d.i)) { errore_imposta(st->err, n->riga, n->col, "overflow intero"); } return val_int(r); }
            if (op == OP_DIV || op == OP_MOD) {
                if (b.d.i == 0) { errore_imposta(st->err, n->riga, n->col, "divisione per zero"); return val_nullo(); }
                if (a.d.i == INT64_MIN && b.d.i == -1) { errore_imposta(st->err, n->riga, n->col, "overflow intero"); return val_nullo(); }
                return val_int((op == OP_DIV) ? (a.d.i / b.d.i) : (a.d.i % b.d.i));
            }
            if (op == OP_LT) { return val_bool(a.d.i < b.d.i); }
            if (op == OP_LE) { return val_bool(a.d.i <= b.d.i); }
            if (op == OP_GT) { return val_bool(a.d.i > b.d.i); }
            return val_bool(a.d.i >= b.d.i);
        }
        case AST_CHIAMATA: {
            funzione_t *fn = ht_cerca(st->funzioni, n->d.chiamata.nome);
            if (fn == nullptr) { errore_imposta(st->err, n->riga, n->col, "funzione non definita"); return val_nullo(); }
            if (n->d.chiamata.n_args != fn->arita) { errore_imposta(st->err, n->riga, n->col, "numero di argomenti errato"); return val_nullo(); }
            valore_t args[8] = {};
            if (fn->arita > 8) { errore_imposta(st->err, n->riga, n->col, "troppi argomenti"); return val_nullo(); }
            size_t idx = 0;
            for (const arg_t *g = n->d.chiamata.args; g != nullptr; g = g->prox) {
                args[idx++] = valuta_expr(st, g->expr, env);
                if (st->err->attivo) { return val_nullo(); }
            }
            if (fn->predefinita) {
                return fn->d.fn(args, fn->arita, n->riga, n->col, st->err);
            }
            if (st->prof >= MAX_PROF_CHIAMATE) { errore_imposta(st->err, n->riga, n->col, "profondita chiamate eccessiva"); return val_nullo(); }
            ambiente_t *locale = env_crea(st->globale);
            if (locale == nullptr) { errore_imposta(st->err, n->riga, n->col, "memoria esaurita"); return val_nullo(); }
            idx = 0;
            for (const param_t *pm = fn->d.decl->d.fn.params; pm != nullptr; pm = pm->prox) {
                if (!env_def(locale, pm->nome, args[idx++], n->riga, n->col, st->err)) { env_distruggi(locale); return val_nullo(); }
            }
            ++st->prof;
            esegui_blocco(st, fn->d.decl->d.fn.corpo, locale);
            --st->prof;
            valore_t ris = st->in_ritorno ? st->val_ritorno : val_nullo();
            st->in_ritorno = false;
            st->val_ritorno = val_nullo();
            env_distruggi(locale);
            return ris;
        }
        default: return val_nullo();
    }
}

static void esegui_stmt(stato_eval_t *st, const nodo_t *n, ambiente_t *env) {
    if (st->err->attivo || st->in_ritorno) { return; }
    if (++st->passi > MAX_PASSI) { errore_imposta(st->err, n->riga, n->col, "limite passi superato"); return; }
    switch (n->tipo) {
        case AST_DECL_VAR: {
            valore_t v = valuta_expr(st, n->d.var_stmt.expr, env);
            if (!st->err->attivo) { env_def(env, n->d.var_stmt.nome, v, n->riga, n->col, st->err); }
            break;
        }
        case AST_ASS: {
            valore_t v = valuta_expr(st, n->d.var_stmt.expr, env);
            if (st->err->attivo) { break; }
            valore_t *es = env_cerca(env, n->d.var_stmt.nome);
            if (es == nullptr) { errore_imposta(st->err, n->riga, n->col, "variabile non dichiarata"); }
            else { *es = v; }
            break;
        }
        case AST_STAMPA: {
            valore_t v = valuta_expr(st, n->d.expr, env);
            if (!st->err->attivo) { char buf[64]; val_formatta(v, buf, sizeof(buf)); out_appendi(st->out, buf); }
            break;
        }
        case AST_IF: {
            valore_t c = valuta_expr(st, n->d.sel.cond, env);
            if (st->err->attivo) { break; }
            if (c.tipo != VAL_BOOL) { errore_imposta(st->err, n->riga, n->col, "condizione if richiede bool"); break; }
            const nodo_t *ramo = c.d.b ? n->d.sel.ramo_v : n->d.sel.ramo_f;
            if (ramo != nullptr) {
                if (ramo->tipo == AST_BLOCCO) {
                    ambiente_t *sub = env_crea(env);
                    if (sub == nullptr) { errore_imposta(st->err, n->riga, n->col, "memoria esaurita"); break; }
                    esegui_blocco(st, ramo, sub);
                    env_distruggi(sub);
                } else {
                    esegui_stmt(st, ramo, env);
                }
            }
            break;
        }
        case AST_WHILE: {
            while (!st->err->attivo && !st->in_ritorno) {
                valore_t c = valuta_expr(st, n->d.ciclo.cond, env);
                if (st->err->attivo) { break; }
                if (c.tipo != VAL_BOOL) { errore_imposta(st->err, n->riga, n->col, "condizione while richiede bool"); break; }
                if (!c.d.b) { break; }
                ambiente_t *sub = env_crea(env);
                if (sub == nullptr) { errore_imposta(st->err, n->riga, n->col, "memoria esaurita"); break; }
                esegui_blocco(st, n->d.ciclo.corpo, sub);
                env_distruggi(sub);
            }
            break;
        }
        case AST_FN: {
            char *k = strdup(n->d.fn.nome);
            funzione_t *f = malloc(sizeof(*f));
            if (k == nullptr || f == nullptr) { free(k); free(f); errore_imposta(st->err, n->riga, n->col, "memoria esaurita"); break; }
            *f = (funzione_t){.predefinita = false, .arita = n->d.fn.n_params, .d.decl = n};
            if (ht_inserisci(st->funzioni, k, f) < 0) { free(k); free(f); errore_imposta(st->err, n->riga, n->col, "memoria esaurita"); }
            break;
        }
        case AST_RETURN: {
            if (st->prof == 0) { errore_imposta(st->err, n->riga, n->col, "return fuori da funzione"); break; }
            valore_t v = (n->d.expr != nullptr) ? valuta_expr(st, n->d.expr, env) : val_nullo();
            if (!st->err->attivo) { st->in_ritorno = true; st->val_ritorno = v; }
            break;
        }
        case AST_EXPR_STMT: (void)valuta_expr(st, n->d.expr, env); break;
        default: break;
    }
}

static void esegui_blocco(stato_eval_t *st, const nodo_t *blocco, ambiente_t *env) {
    for (const nodo_t *s = blocco->d.lista; s != nullptr && !st->err->attivo && !st->in_ritorno; s = s->prox) {
        esegui_stmt(st, s, env);
    }
}

bool minil_esegui(const char *sorgente, out_buf_t *out, errore_t *err) {
    *out = (out_buf_t){};
    *err = (errore_t){};
    arena_t arena = {};
    ambiente_t *globale = nullptr;
    tabella_hash_t *funzioni = nullptr;
    bool ok = false;
    if (!arena_crea(&arena, 65536)) { errore_imposta(err, 1, 1, "memoria arena esaurita"); goto cleanup; }
    nodo_t *prog = parse_programma(&arena, sorgente, err);
    if (prog == nullptr) { goto cleanup; }
    globale = env_crea(nullptr);
    funzioni = ht_crea(&(ht_config_t){.cap_iniziale = 16, .hash = ht_hash_stringa, .uguali = ht_uguali_stringa, .distruggi_chiave = free, .distruggi_valore = free});
    if (globale == nullptr || funzioni == nullptr) { errore_imposta(err, 1, 1, "memoria esaurita"); goto cleanup; }
    if (!registra_builtin(funzioni, "abs", 1, bi_abs) || !registra_builtin(funzioni, "min", 2, bi_min) ||
        !registra_builtin(funzioni, "max", 2, bi_max) || !registra_builtin(funzioni, "pot", 2, bi_pot)) {
        errore_imposta(err, 1, 1, "memoria esaurita");
        goto cleanup;
    }
    stato_eval_t st = {.globale = globale, .funzioni = funzioni, .out = out, .err = err};
    esegui_blocco(&st, prog, globale);
    ok = !err->attivo;
cleanup:
    ht_distruggi(funzioni);
    env_distruggi(globale);
    arena_distruggi(&arena);
    return ok;
}

soluzione_file.test_fw.h:
#ifndef TEST_FW_H
#define TEST_FW_H

#include <stddef.h>
#include <stdio.h>
#include <string.h>

typedef struct test_ctx {
    size_t eseguiti, superati, falliti;
    bool corrente_ko;
} test_ctx_t;

typedef void (*test_fn)(test_ctx_t *ctx);
typedef struct caso_test { const char *nome; test_fn fn; } caso_test_t;

#define T_VERO(ctx, cond) do { \
    if (!(cond)) { (ctx)->corrente_ko = true; printf("  [ASS_FAIL] %s: %s\n", __func__, #cond); } \
} while (0)

#define T_EQ_STR(ctx, att, ott) do { \
    const char *_a = (att), *_o = (ott); \
    if (strcmp(_a, _o) != 0) { (ctx)->corrente_ko = true; printf("  [ASS_FAIL] %s: att='%s' ott='%s'\n", __func__, _a, _o); } \
} while (0)

static inline void test_esegui(test_ctx_t *ctx, const caso_test_t *c) {
    ctx->corrente_ko = false;
    c->fn(ctx);
    ++ctx->eseguiti;
    if (ctx->corrente_ko) { ++ctx->falliti; printf("[FAIL] %s\n", c->nome); }
    else { ++ctx->superati; printf("[PASS] %s\n", c->nome); }
}

#endif

soluzione_file.main.c:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "eval.h"
#include "test_fw.h"

static void t_aritmetica(test_ctx_t *c) {
    out_buf_t o; errore_t e;
    T_VERO(c, minil_esegui("stampa 10 - 3 - 2; stampa 2 + 3 * 4; stampa -(1 + 2) * 3;", &o, &e));
    T_EQ_STR(c, "5\n14\n-9\n", o.dati);
}
static void t_variabili(test_ctx_t *c) {
    out_buf_t o; errore_t e;
    const char *s = "var x = 10; var y = 1; if (true) { var x = 99; y = 2; stampa x; } stampa x; stampa y;";
    T_VERO(c, minil_esegui(s, &o, &e));
    T_EQ_STR(c, "99\n10\n2\n", o.dati);
}
static void t_booleani(test_ctx_t *c) {
    out_buf_t o; errore_t e;
    const char *s = "var x = 0; stampa (x != 0 && 10 / x > 1); stampa (x == 0 || 10 / x > 1); stampa !false;";
    T_VERO(c, minil_esegui(s, &o, &e));
    T_EQ_STR(c, "false\ntrue\ntrue\n", o.dati);
}
static void t_flusso(test_ctx_t *c) {
    out_buf_t o; errore_t e;
    const char *s = "var a = 54; var b = 24; while (b != 0) { var r = a % b; a = b; b = r; } if (a == 6) { stampa a; } else { stampa 0; }";
    T_VERO(c, minil_esegui(s, &o, &e));
    T_EQ_STR(c, "6\n", o.dati);
}
static void t_ricorsione(test_ctx_t *c) {
    out_buf_t o; errore_t e;
    const char *s = "fn fib(n) { if (n <= 1) { return n; } return fib(n - 1) + fib(n - 2); } stampa fib(7); stampa fib(10);";
    T_VERO(c, minil_esegui(s, &o, &e));
    T_EQ_STR(c, "13\n55\n", o.dati);
}
static void t_builtin(test_ctx_t *c) {
    out_buf_t o; errore_t e;
    const char *s = "stampa abs(-15); stampa min(4, 9); stampa max(4, 9); stampa pot(3, 4);";
    T_VERO(c, minil_esegui(s, &o, &e));
    T_EQ_STR(c, "15\n4\n9\n81\n", o.dati);
}
static void t_err_sintassi(test_ctx_t *c) {
    out_buf_t o; errore_t e;
    T_VERO(c, !minil_esegui("var x = @;", &o, &e));
    T_VERO(c, !minil_esegui("var x = (1 + 2;", &o, &e));
    T_VERO(c, !minil_esegui("var x = 99999999999999999999;", &o, &e));
}
static void t_err_runtime(test_ctx_t *c) {
    out_buf_t o; errore_t e;
    T_VERO(c, !minil_esegui("stampa 5 / 0;", &o, &e));
    T_VERO(c, !minil_esegui("stampa 9223372036854775807 + 1;", &o, &e));
    T_VERO(c, !minil_esegui("if (1) { stampa 0; }", &o, &e));
    T_VERO(c, !minil_esegui("stampa ignota;", &o, &e));
    T_VERO(c, !minil_esegui("stampa abs(1, 2);", &o, &e));
    T_VERO(c, !minil_esegui("while (true) { var k = 1; }", &o, &e));
}

static void esegui_suite(void) {
    static const caso_test_t SUITE[] = {
        {"aritmetica_precedenza", t_aritmetica}, {"variabili_ambiti", t_variabili},
        {"booleani_corto_circuito", t_booleani}, {"if_else_while_mcd", t_flusso},
        {"funzioni_ricorsive", t_ricorsione}, {"funzioni_predefinite", t_builtin},
        {"errori_lessicali_sintattici", t_err_sintassi}, {"errori_esecuzione", t_err_runtime}
    };
    test_ctx_t ctx = {};
    for (size_t i = 0; i < sizeof(SUITE) / sizeof(SUITE[0]); ++i) { test_esegui(&ctx, &SUITE[i]); }
    printf("RIEPILOGO: test=%zu/%zu falliti=%zu\n", ctx.superati, ctx.eseguiti, ctx.falliti);
}

int main(void) {
    char riga[256], cmd[24], extra = '\0';
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%23s", cmd) != 1) { continue; }
        if (strcmp(cmd, "RUN_TESTS") == 0 && sscanf(riga, "RUN_TESTS %c", &extra) != 1) {
            esegui_suite();
        } else if (strcmp(cmd, "EXEC") == 0 && sscanf(riga, "EXEC %c", &extra) != 1) {
            char src[4096] = {}; size_t tot = 0;
            while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
                if (sscanf(riga, "%23s %c", cmd, &extra) == 1 && strcmp(cmd, "END") == 0) { break; }
                size_t n = strlen(riga);
                if (tot + n >= sizeof(src)) { return EXIT_FAILURE; }
                memcpy(src + tot, riga, n); tot += n;
            }
            src[tot] = '\0';
            out_buf_t out = {}; errore_t err = {};
            if (minil_esegui(src, &out, &err)) {
                printf("--- OUTPUT ---\n%s--- OK ---\n", out.dati);
            } else {
                printf("--- ERRORE %zu:%zu: %s ---\n", err.riga, err.col, err.msg);
            }
        } else {
            fprintf(stderr, "Errore: comando non valido.\n");
            return EXIT_FAILURE;
        }
    }
    return EXIT_SUCCESS;
}
